"use client";

import { createContext, useContext, useEffect, useState } from "react";

export const REGIONS = [
  { value: "worldwide", label: "Worldwide" },
  { value: "africa", label: "Africa" },
  { value: "asia", label: "Asia" },
  { value: "europe", label: "Europe" },
  { value: "middle-east", label: "Middle East" },
  { value: "north-america", label: "North America" },
  { value: "south-america", label: "South America" },
  { value: "oceania", label: "Oceania" },
] as const;

export type Region = (typeof REGIONS)[number]["value"];

type RegionContextValue = {
  region: Region;
  setRegion: (region: Region) => void;
};

const RegionContext = createContext<RegionContextValue | null>(null);

export function RegionProvider({ children }: { children: React.ReactNode }) {
  const [region, setRegion] = useState<Region>("worldwide");

  useEffect(() => {
    const savedRegion = window.localStorage.getItem("hackera-region");
    if (REGIONS.some(({ value }) => value === savedRegion)) setRegion(savedRegion as Region);
  }, []);

  useEffect(() => {
    window.localStorage.setItem("hackera-region", region);
  }, [region]);

  return <RegionContext.Provider value={{ region, setRegion }}>{children}</RegionContext.Provider>;
}

export function useRegion() {
  const context = useContext(RegionContext);
  if (!context) throw new Error("useRegion must be used within RegionProvider");
  return context;
}

export function RegionSelector() {
  const { region, setRegion } = useRegion();

  return (
    <label className="region-selector">
      <span className="sr-only">Select region</span>
      <select
        value={region}
        onChange={(event) => setRegion(event.target.value as Region)}
        aria-label="Select region"
      >
        {REGIONS.map(({ value, label }) => (
          <option key={value} value={value}>{label}</option>
        ))}
      </select>
    </label>
  );
}
